tables = [t for (t,) in con.execute("select name from sqlite_master where type='table' order by name")]
empty = set()
print("=== TABLE ROW COUNTS ===")
for t in tables:
    n = con.execute(f'select count(*) from "{t}"').fetchone()[0]
    if n == 0: empty.add(t)
